@Test
public void testAddTrackerRemoveTrackerActiveMessageMetadataGetsUpdated() {
    String workId = "work-item-id1";
    ActiveMessageMetadata testMetadata = ActiveMessageMetadata.create(step1act1.getStepName().userName(), Stopwatch.createStarted());
