    assertThat(computationStateCache.totalCurrentActiveGetWorkBudget()).isEqualTo(GetWorkBudget.builder().setItems(3).setBytes(work1.getWorkItem().getSerializedSize() + work2.getWorkItem().getSerializedSize() + work3.getWorkItem().getSerializedSize()).build());
}

