@Test
public void testFetchGlobalDataBasic() throws Exception {
    SideInputStateFetcherFactory factory = SideInputStateFetcherFactory.fromOptions(PipelineOptionsFactory.as(DataflowStreamingPipelineOptions.class));
    SideInputStateFetcher fetcher = factory.createSideInputStateFetcher(server::getSideInputData);
    ByteStringOutputStream stream = new ByteStringOutputStream();
    ListCoder.of(StringUtf8Coder.of()).encode(Collections.singletonList("data"), stream, Coder.Context.OUTER);
    ByteString encodedIterable = stream.toByteString();
    PCollectionView<String> view = TestPipeline.create().apply(Create.empty(StringUtf8Coder.of())).apply(View.asSingleton());
    String tag = view.getTagInternal().getId();
    // Test three calls in a row. First, data is not ready, then data is ready,
    // then the data is already cached.
    when(server.getSideInputData(any(Windmill.GlobalDataRequest.class))).thenReturn(buildGlobalDataResponse(tag, false, null), buildGlobalDataResponse(tag, true, encodedIterable));
    assertFalse(fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier).isReady());
    assertFalse(fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier).isReady());
    assertEquals("data", fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.KNOWN_READY, readStateSupplier).value().orElse(null));
    assertEquals("data", fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.KNOWN_READY, readStateSupplier).value().orElse(null));
    verify(server, times(2)).getSideInputData(buildGlobalDataRequest(tag));
    verifyNoMoreInteractions(server);
}

