@Test
public void testTrackSingleCall_exceptionThrown() throws InterruptedException {
    doNothing().when(memoryMonitor).waitForResources(anyString());
    CountDownLatch callProcessing = new CountDownLatch(1);
    CountDownLatch beforeException = new CountDownLatch(1);
    CountDownLatch afterException = new CountDownLatch(1);
    // Catch the exception outside the try-with-resources block to ensure that
    // AutoCloseable.closed() runs in the midst of an exception.
    getDataProcessor.submit(() -> {
        try {
            try (AutoCloseable ignored = getDataMetricTracker.trackStateDataFetchWithThrottling()) {
                callProcessing.countDown();
                beforeException.await();
                throw new RuntimeException("something bad happened");
            }
        } catch (RuntimeException e) {
            afterException.countDown();
            throw e;
        }
    });
    callProcessing.await();
    ThrottlingGetDataMetricTracker.ReadOnlySnapshot metricsWhileProcessing = getDataMetricTracker.getMetricsSnapshot();
    assertThat(metricsWhileProcessing.activeStateReads()).isEqualTo(1);
    beforeException.countDown();
    // In the midst of an exception, close() should still run.
    afterException.await();
    ThrottlingGetDataMetricTracker.ReadOnlySnapshot metricsAfterProcessing = getDataMetricTracker.getMetricsSnapshot();
    assertThat(metricsAfterProcessing.activeStateReads()).isEqualTo(0);
}

/**
 * Have the memory monitor block when waitForResources is called simulating memory pressure.
 */
private CountDownLatch simulateMemoryPressure() {
    CountDownLatch mockThrottler = new CountDownLatch(1);
    doAnswer(invocationOnMock -> {
        mockThrottler.await();
        return null;
    }).when(memoryMonitor).waitForResources(anyString());
    return mockThrottler;
}

@Test
public void testShutdown_abortsQueuedCommits() throws InterruptedException {
    int numCommits = 5;
    CountDownLatch commitProcessed = new CountDownLatch(numCommits);
    Set<Windmill.CommitStatus> onDone = new HashSet<>();
    TestCommitWorkStreamRequestObserver requestObserver = spy(new TestCommitWorkStreamRequestObserver());
    CommitWorkStreamTestStub testStub = new CommitWorkStreamTestStub(requestObserver);
    GrpcCommitWorkStream commitWorkStream = createCommitWorkStream(testStub);
    InOrder requestObserverVerifier = inOrder(requestObserver);
    try (WindmillStream.CommitWorkStream.RequestBatcher batcher = commitWorkStream.batcher()) {
        for (int i = 0; i < numCommits; i++) {
            batcher.commitWorkItem(COMPUTATION_ID, workItemCommitRequest(i), commitStatus -> {
                onDone.add(commitStatus);
                commitProcessed.countDown();
            });
        }
    } catch (StreamObserverCancelledException ignored) {
    }
    // Verify that we sent the commits above in a request + the initial header.
    requestObserverVerifier.verify(requestObserver).onNext(argThat(request -> request.getHeader().equals(TEST_JOB_HEADER)));
    requestObserverVerifier.verify(requestObserver).onNext(argThat(request -> !request.getCommitChunkList().isEmpty()));
    requestObserverVerifier.verifyNoMoreInteractions();
    // We won't get responses so we will have some pending requests.
    assertTrue(commitWorkStream.hasPendingRequests());
    commitWorkStream.shutdown();
    commitProcessed.await();
    assertThat(onDone).containsExactly(Windmill.CommitStatus.ABORTED);
}

