@Test
public void testGetWorkerMetadata_consumesSubsequentResponseMetadata() {
    WorkerMetadataResponse initialResponse = WorkerMetadataResponse.newBuilder().setMetadataVersion(1).addAllWorkEndpoints(DIRECT_PATH_ENDPOINTS).putAllGlobalDataEndpoints(GLOBAL_DATA_ENDPOINTS).setExternalEndpoint(AUTHENTICATING_SERVICE).build();
    TestWindmillEndpointsConsumer testWindmillEndpointsConsumer = Mockito.spy(new TestWindmillEndpointsConsumer());
    GetWorkerMetadataTestStub testStub = new GetWorkerMetadataTestStub(new TestGetWorkMetadataRequestObserver());
    stream = getWorkerMetadataTestStream(testStub, testWindmillEndpointsConsumer);
    testStub.injectWorkerMetadata(initialResponse);
    List<WorkerMetadataResponse.Endpoint> newDirectPathEndpoints = Lists.newArrayList(WorkerMetadataResponse.Endpoint.newBuilder().setDirectEndpoint(IPV6_ADDRESS_2).build());
    Map<String, WorkerMetadataResponse.Endpoint> newGlobalDataEndpoints = new HashMap<>();
    newGlobalDataEndpoints.put("new_global_data", WorkerMetadataResponse.Endpoint.newBuilder().setDirectEndpoint(IPV6_ADDRESS_2).build());
    WorkerMetadataResponse newWorkMetadataResponse = WorkerMetadataResponse.newBuilder().setMetadataVersion(initialResponse.getMetadataVersion() + 1).addAllWorkEndpoints(newDirectPathEndpoints).putAllGlobalDataEndpoints(newGlobalDataEndpoints).setExternalEndpoint(AUTHENTICATING_SERVICE).build();
    testStub.injectWorkerMetadata(newWorkMetadataResponse);
    assertThat(newGlobalDataEndpoints.keySet()).containsExactlyElementsIn(testWindmillEndpointsConsumer.globalDataEndpoints.keySet());
    assertThat(testWindmillEndpointsConsumer.windmillEndpoints).containsExactlyElementsIn(newDirectPathEndpoints.stream().map(endpointProto -> WindmillEndpoints.Endpoint.from(endpointProto, AUTHENTICATING_SERVICE)).collect(Collectors.toList()));
}

