public void handleCleanupWhenInputSenderFails() throws Exception {
    RuntimeException testException = new RuntimeException();
    BeamFnDataOutboundAggregator mockInputSender = mock(BeamFnDataOutboundAggregator.class);
    CompletableFuture<InstructionResponse> processBundleResponseFuture = new CompletableFuture<>();
    when(fnApiControlClient.handle(any(BeamFnApi.InstructionRequest.class))).thenReturn(processBundleResponseFuture);
    FullWindowedValueCoder<String> coder = FullWindowedValueCoder.of(StringUtf8Coder.of(), Coder.INSTANCE);
    BundleProcessor processor = sdkHarnessClient.getProcessor(descriptor, Collections.singletonList(RemoteInputDestination.of((FullWindowedValueCoder) coder, SDK_GRPC_READ_TRANSFORM)));
    doNothing().when(dataService).registerReceiver(any(), outputReceiverCaptor.capture());
    when(dataService.createOutboundAggregator(any(), anyBoolean())).thenReturn(mockInputSender);
    doThrow(testException).when(mockInputSender).sendOrCollectBufferedDataAndFinishOutboundStreams();
    BundleProgressHandler mockProgressHandler = mock(BundleProgressHandler.class);
    try {
        try (RemoteBundle activeBundle = processor.newBundle(ImmutableMap.of(SDK_GRPC_WRITE_TRANSFORM, RemoteOutputReceiver.of(ByteArrayCoder.of(), mock(FnDataReceiver.class))), mockProgressHandler)) {
            // We shouldn't be required to complete the process bundle response future.
        }
        fail("Exception expected");
    } catch (Exception e) {
        assertEquals(testException, e);
        // We expect that we don't register the receiver and the next accept call will raise an error
        // making the data service aware of the error.
        verify(dataService, never()).unregisterReceiver(any());
        assertThrows("Inbound observer closed.", Exception.class, () -> outputReceiverCaptor.getValue().accept(Elements.getDefaultInstance()));
    }
}

