    samzaTransformMetricRegistry.register("filter", "dummy-pvalue.in", mock(Context.class));
    samzaTransformMetricRegistry.register("filter", "dummy-pvalue.out", mock(Context.class));
    // Update the avg arrival time
    samzaTransformMetricRegistry.updateArrivalTimeMap("filter", "dummy-pvalue.in", watermarkMessage.getTimestamp(), avgInputArrivalTime);
    samzaTransformMetricRegistry.updateArrivalTimeMap("filter", "dummy-pvalue.out", watermarkMessage.getTimestamp(), avgInputArrivalTime + 100);
    // Check the avg arrival time is updated
    assertEquals(avgInputArrivalTime, samzaTransformMetricRegistry.getAverageArrivalTimeMap("filter").get("dummy-pvalue.in").get(watermarkMessage.getTimestamp()).longValue());
