private void testWatermarkHoldWhenPendingBundleInProgress(OpEmitter<String> mockEmitter, ArgumentCaptor<CompletionStage<Collection<WindowedValue<String>>>> captor, Instant watermark) {
    // Starts the bundle and reach the max bundle size so that tryFinishBundle() seals the current
