@Test
public void constructionFailures() {
    // Not nested schema (no headers)
    assertThrows(IllegalArgumentException.class, () -> newTable(Schema.builder().addByteArrayField(Schemas.PAYLOAD_FIELD).build(), Optional.empty()));
    // Row payload without serializer
    assertThrows(IllegalArgumentException.class, () -> newTable(Schema.builder().addRowField(Schemas.PAYLOAD_FIELD, Schema.builder().addStringField("abc").build()).addField(Schemas.HEADERS_FIELD, Schemas.HEADERS_FIELD_TYPE).build(), Optional.empty()));
    // Bytes payload with serializer
    assertThrows(IllegalArgumentException.class, () -> newTable(Schema.builder().addByteArrayField(Schemas.PAYLOAD_FIELD).addField(Schemas.HEADERS_FIELD, Schemas.HEADERS_FIELD_TYPE).build(), Optional.of(serializer)));
    // Bad field in schema
    assertThrows(IllegalArgumentException.class, () -> newTable(Schema.builder().addByteArrayField(Schemas.PAYLOAD_FIELD).addField(Schemas.HEADERS_FIELD, Schemas.HEADERS_FIELD_TYPE).addBooleanField("bad").build(), Optional.empty()));
    // Bad field type in schema
    assertThrows(IllegalArgumentException.class, () -> newTable(Schema.builder().addByteArrayField(Schemas.PAYLOAD_FIELD).addField(Schemas.HEADERS_FIELD, Schemas.HEADERS_FIELD_TYPE).addBooleanField(Schemas.EVENT_TIMESTAMP_FIELD).build(), Optional.empty()));
}

@Test
public void rowToRecordFailures() {
    Schema payloadSchema = Schema.builder().addStringField("def").build();
    Schema schema = Schema.builder().addRowField(Schemas.PAYLOAD_FIELD, payloadSchema).addField(Schemas.HEADERS_FIELD, Schemas.HEADERS_FIELD_TYPE.withNullable(true)).build();
    NestedPayloadKafkaTable table = newTable(schema, Optional.of(serializer));
    // badRow cannot be cast to schema
    Schema badRowSchema = Schema.builder().addStringField("xxx").build();
    Row badRow = Row.withSchema(badRowSchema).attachValues(Row.withSchema(badRowSchema).attachValues("abc"));
    assertThrows(IllegalArgumentException.class, () -> table.transformOutput(badRow));
    Row goodRow = Row.withSchema(schema).withFieldValue(Schemas.PAYLOAD_FIELD, Row.withSchema(payloadSchema).withFieldValue("def", "abc").build()).build();
    doThrow(new IllegalArgumentException("")).when(serializer).serialize(any());
    assertThrows(IllegalArgumentException.class, () -> table.transformOutput(goodRow));
}

@Test
public void constructionFailures() {
    // Row payload without serializer
    assertThrows(IllegalArgumentException.class, () -> new RowHandler(Schema.builder().addRowField(RowHandler.PAYLOAD_FIELD, Schema.builder().addStringField("abc").build()).build()));
    // Bytes payload with serializer
    assertThrows(IllegalArgumentException.class, () -> new RowHandler(Schema.builder().addByteArrayField(RowHandler.PAYLOAD_FIELD).build(), serializer));
}

@Test
public void rowToMessageFailures() {
    Schema payloadSchema = Schema.builder().addStringField("def").build();
    Schema schema = Schema.builder().addRowField(RowHandler.PAYLOAD_FIELD, payloadSchema).build();
    RowHandler rowHandler = new RowHandler(schema, serializer);
    // badRow cannot be cast to schema
    Schema badRowSchema = Schema.builder().addStringField("xxx").build();
    Row badRow = Row.withSchema(badRowSchema).attachValues(Row.withSchema(badRowSchema).attachValues("abc"));
    assertThrows(IllegalArgumentException.class, () -> rowHandler.rowToMessage(badRow));
    Row goodRow = Row.withSchema(schema).addValue(Row.withSchema(payloadSchema).attachValues("abc")).build();
    doThrow(new IllegalArgumentException("")).when(serializer).serialize(any());
    assertThrows(IllegalArgumentException.class, () -> rowHandler.rowToMessage(goodRow));
}

