public void testReadFromBigQueryAvroObjectsMutation() throws Exception {
    ReadSession readSession = ReadSession.newBuilder().setName("readSession").setAvroSchema(AvroSchema.newBuilder().setSchema(AVRO_SCHEMA_STRING)).build();
    ReadRowsRequest expectedRequest = ReadRowsRequest.newBuilder().setReadStream("readStream").build();
    List<GenericRecord> records = Lists.newArrayList(createRecord("A", 1, AVRO_SCHEMA), createRecord("B", 2, AVRO_SCHEMA));
    List<ReadRowsResponse> responses = Lists.newArrayList(createResponse(AVRO_SCHEMA, records.subList(0, 1), 0.0, 0.5), createResponse(AVRO_SCHEMA, records.subList(1, 2), 0.5, 1.0));
    StorageClient fakeStorageClient = mock(StorageClient.class);
    when(fakeStorageClient.readRows(expectedRequest, "")).thenReturn(new FakeBigQueryServerStream<>(responses));
    BigQueryStorageStreamSource<GenericRecord> streamSource = BigQueryStorageStreamSource.create(readSession, ReadStream.newBuilder().setName("readStream").build(), TABLE_SCHEMA, SchemaAndRecord::getRecord, AvroCoder.of(AVRO_SCHEMA), new FakeBigQueryServices().withStorageClient(fakeStorageClient));
    BoundedReader<GenericRecord> reader = streamSource.createReader(options);
    // Reads A.
    assertTrue(reader.start());
