@Test
public void testUsingCredentialsFromBigtableOptions() throws Exception {
    Credentials fakeCredentials = Mockito.mock(Credentials.class);
    BigtableOptions options = BigtableOptions.builder().setProjectId("project").setInstanceId("instance").setAppProfileId("app-profile").setCredentialOptions(CredentialOptions.UserSuppliedCredentialOptions.credential(fakeCredentials)).build();
    GcpOptions pipelineOptions = PipelineOptionsFactory.as(GcpOptions.class);
    pipelineOptions.setGcpCredential(new TestCredential());
    BigtableConfig config = BigtableConfig.builder().setValidate(true).build();
    config = BigtableConfigTranslator.translateToBigtableConfig(config, options);
    BigtableDataSettings veneerSettings = BigtableConfigTranslator.translateToVeneerSettings(config, pipelineOptions);
    assertNotNull(veneerSettings.getStubSettings().getCredentialsProvider());
    assertEquals(fakeCredentials, veneerSettings.getStubSettings().getCredentialsProvider().getCredentials());
}

