/**
 * This test verifies that a refill request is sent before we read all the rows in the buffer.
 */
@Test
public void testRefillOnLowWatermark() throws IOException {
    int segmentSize = 30;
    RowSet.Builder ranges = RowSet.newBuilder();
    // generate 3 pages of rows
    ranges.addRowRanges(generateRowRange(generateByteString(DEFAULT_PREFIX, 0), generateByteString(DEFAULT_PREFIX, segmentSize * 3)));
    List<List<Row>> expectedResults = ImmutableList.of(generateSegmentResult(DEFAULT_PREFIX, 0, segmentSize), generateSegmentResult(DEFAULT_PREFIX, segmentSize, segmentSize), generateSegmentResult(DEFAULT_PREFIX, segmentSize * 2, segmentSize), ImmutableList.of());
    // Set up Callable to be returned by stub.createReadRowsCallable()
    ServerStreamingCallable<Query, Row> mockCallable = Mockito.mock(ServerStreamingCallable.class);
    // Return multiple answers when mockCallable is called
    doAnswer(new MultipleAnswer<Row>(expectedResults)).when(mockCallable).call(any(Query.class), any(ResponseObserver.class), any(ApiCallContext.class));
    when(mockStub.createReadRowsCallable(any(RowAdapter.class))).thenReturn(mockCallable);
    ServerStreamingCallable<Query, Row> callable = mockStub.createReadRowsCallable(new BigtableServiceImpl.BigtableRowProtoAdapter());
    // Set up client to return callable
    when(mockBigtableDataClient.readRowsCallable(any(RowAdapter.class))).thenReturn(callable);
    BigtableService.Reader underTest = new BigtableServiceImpl.BigtableSegmentReaderImpl(mockBigtableDataClient, bigtableDataSettings.getProjectId(), bigtableDataSettings.getInstanceId(), TABLE_ID, ranges.build(), RowFilter.getDefaultInstance(), segmentSize, DEFAULT_BYTE_SEGMENT_SIZE, mockCallMetric);
    Assert.assertTrue(underTest.start());
    int refillWatermark = Math.max(1, (int) (segmentSize * 0.1));
    Assert.assertTrue(refillWatermark > 1);
    // Make sure refill happens on the second page. At this point, there
    // should be 3 calls made on the callable.
    for (int i = 0; i < segmentSize * 2 - refillWatermark + 1; i++) {
        underTest.getCurrentRow();
        underTest.advance();
    }
    verify(callable, times(3)).call(queryCaptor.capture(), any(ResponseObserver.class), any(ApiCallContext.class));
}

