/**
 * This test ensures the Exception handling inside of the scanHandler. This test will check if a
 * StatusRuntimeException was thrown.
 *
 * @throws IOException
 */
@Test
public void testReadSegmentExceptionHandling() throws IOException {
    RowSet.Builder ranges = RowSet.newBuilder();
    ranges.addRowRanges(generateRowRange(generateByteString(DEFAULT_PREFIX, 0), generateByteString(DEFAULT_PREFIX, 1)));
    // Set up Callable to be returned by stub.createReadRowsCallable()
    ServerStreamingCallable<Query, Row> mockCallable = Mockito.mock(ServerStreamingCallable.class);
    doAnswer(new Answer<Void>() {

        @Override
        public Void answer(InvocationOnMock invocationOnMock) throws Throwable {
            new Thread() {

                @Override
                public void run() {
                    ((ResponseObserver) invocationOnMock.getArgument(1)).onError(Status.INVALID_ARGUMENT.asRuntimeException());
                }
            }.start();
            return null;
        }
    }).when(mockCallable).call(any(Query.class), any(ResponseObserver.class), any(ApiCallContext.class));
    when(mockStub.createReadRowsCallable(any(RowAdapter.class))).thenReturn(mockCallable);
    ServerStreamingCallable<Query, Row> callable = mockStub.createReadRowsCallable(new BigtableServiceImpl.BigtableRowProtoAdapter());
    // Set up client to return callable
    when(mockBigtableDataClient.readRowsCallable(any(RowAdapter.class))).thenReturn(callable);
    BigtableService.Reader underTest = new BigtableServiceImpl.BigtableSegmentReaderImpl(mockBigtableDataClient, bigtableDataSettings.getProjectId(), bigtableDataSettings.getInstanceId(), TABLE_ID, ranges.build(), RowFilter.getDefaultInstance(), SEGMENT_SIZE, DEFAULT_BYTE_SEGMENT_SIZE, mockCallMetric);
    IOException returnedError = null;
    try {
        underTest.start();
    } catch (IOException e) {
        returnedError = e;
    }
    Assert.assertTrue(returnedError.getCause() instanceof StatusRuntimeException);
    Mockito.verify(mockCallMetric, Mockito.times(1)).call(Status.INVALID_ARGUMENT.getCode().toString());
}

@Test
public void testHeartBeat() {
