    ChangeStreamContinuationToken changeStreamContinuationToken = ChangeStreamContinuationToken.create(ByteStringRange.create("a", "b"), "1234");
    CloseStream mockCloseStream = Mockito.mock(CloseStream.class);
    Status statusProto = Status.newBuilder().setCode(11).build();
    Mockito.when(mockCloseStream.getStatus()).thenReturn(com.google.cloud.bigtable.common.Status.fromProto(statusProto));
    Mockito.when(mockCloseStream.getChangeStreamContinuationTokens()).thenReturn(Collections.singletonList(changeStreamContinuationToken));
    final Optional<DoFn.ProcessContinuation> result = action.run(partitionRecord, mockCloseStream, tracker, receiver, watermarkEstimator, throughputEstimator);
    assertTrue(result.isPresent());
    assertEquals(DoFn.ProcessContinuation.resume(), result.get());
    verify(metrics).incClosestreamCount();
    StreamProgress streamProgress = new StreamProgress(mockCloseStream);
    verify(tracker).tryClaim(eq(streamProgress));
}

@Test
public void testChangeStreamMutationUser() {
    ByteStringRange partition = ByteStringRange.create("", "");
    when(partitionRecord.getPartition()).thenReturn(partition);
    final Instant commitTimestamp = Instant.ofEpochMilli(1_000L);
    final Instant lowWatermark = Instant.ofEpochMilli(500L);
    ChangeStreamContinuationToken changeStreamContinuationToken = ChangeStreamContinuationToken.create(ByteStringRange.create("", ""), "1234");
    ChangeStreamMutation changeStreamMutation = Mockito.mock(ChangeStreamMutation.class);
    Mockito.when(changeStreamMutation.getCommitTimestamp()).thenReturn(toThreetenInstant(commitTimestamp));
    Mockito.when(changeStreamMutation.getToken()).thenReturn("1234");
    Mockito.when(changeStreamMutation.getEstimatedLowWatermark()).thenReturn(toThreetenInstant(lowWatermark));
    Mockito.when(changeStreamMutation.getType()).thenReturn(ChangeStreamMutation.MutationType.USER);
    KV<ByteString, ChangeStreamRecord> record = KV.of(changeStreamMutation.getRowKey(), changeStreamMutation);
    final Optional<DoFn.ProcessContinuation> result = action.run(partitionRecord, changeStreamMutation, tracker, receiver, watermarkEstimator, throughputEstimator);
    assertFalse(result.isPresent());
    verify(metrics).incChangeStreamMutationUserCounter();
    verify(metrics, never()).incChangeStreamMutationGcCounter();
    StreamProgress streamProgress = new StreamProgress(changeStreamContinuationToken, lowWatermark, BigDecimal.valueOf(1000), Instant.now(), false);
    verify(tracker).tryClaim(streamProgressArgumentCaptor.capture());
    assertEquals(streamProgress.getCurrentToken(), streamProgressArgumentCaptor.getValue().getCurrentToken());
    assertEquals(streamProgress.getThroughputEstimate(), streamProgressArgumentCaptor.getValue().getThroughputEstimate());
    assertEquals(streamProgress.getEstimatedLowWatermark(), streamProgressArgumentCaptor.getValue().getEstimatedLowWatermark());
    assertEquals(streamProgress.isHeartbeat(), streamProgressArgumentCaptor.getValue().isHeartbeat());
    verify(receiver).outputWithTimestamp(eq(record), eq(Instant.EPOCH));
    verify(watermarkEstimator).setWatermark(eq(lowWatermark));
    verify(throughputEstimator).update(any(), eq(record));
}

