@Test
public void testUpdateWatermarkOnEvenCountAfter10Seconds() throws Exception {
    // We update watermark every 2 iterations only if it's been more than 10s since the last update.
    OffsetRange offsetRange = new OffsetRange(2, Long.MAX_VALUE);
    when(tracker.currentRestriction()).thenReturn(offsetRange);
    when(tracker.tryClaim(offsetRange.getFrom())).thenReturn(true);
    assertEquals(DoFn.ProcessContinuation.resume().withResumeDelay(Duration.millis(100)), action.run(tracker, receiver, watermarkEstimator, new InitialPipelineState(startTime, false)));
    assertEquals(startTime, watermarkEstimator.currentWatermark());
    assertNull(metadataTableDao.readDetectNewPartitionsState());
    // Manually set the watermark of DNP to start time with a timestamp of 10s prior.
    RowMutation rowMutation = RowMutation.create(MetadataTableAdminDao.DEFAULT_METADATA_TABLE_NAME, metadataTableDao.getChangeStreamNamePrefix().concat(MetadataTableAdminDao.DETECT_NEW_PARTITION_SUFFIX)).setCell(MetadataTableAdminDao.CF_WATERMARK, MetadataTableAdminDao.QUALIFIER_DEFAULT, Instant.now().minus(Duration.standardSeconds(10)).getMillis() * 1000L, startTime.getMillis());
