public void testProcessSplitNewPartitions() throws Exception {
    // Avoid 0 and multiples of 2 so that we can specifically test just reading new partitions.
    OffsetRange offsetRange = new OffsetRange(1, Long.MAX_VALUE);
    when(tracker.currentRestriction()).thenReturn(offsetRange);
    when(tracker.tryClaim(offsetRange.getFrom())).thenReturn(true);
    // ["", "") splits into ["", "a"), ["a","k"), ["k", "")
    Instant watermark = Instant.now();
    ByteStringRange childEmptyA = ByteStringRange.create("", "a");
    ChangeStreamContinuationToken tokenEmptyA = ChangeStreamContinuationToken.create(childEmptyA, ByteStringRange.serializeToByteString(childEmptyA).toStringUtf8());
    NewPartition newPartitionEmptyA = new NewPartition(childEmptyA, Collections.singletonList(tokenEmptyA), watermark);
    metadataTableDao.writeNewPartition(newPartitionEmptyA);
    ByteStringRange childKEmpty = ByteStringRange.create("k", "");
    ChangeStreamContinuationToken tokenKEmpty = ChangeStreamContinuationToken.create(childKEmpty, ByteStringRange.serializeToByteString(childKEmpty).toStringUtf8());
    NewPartition newPartitionKEmpty = new NewPartition(childKEmpty, Collections.singletonList(tokenKEmpty), watermark);
    metadataTableDao.writeNewPartition(newPartitionKEmpty);
    ByteStringRange childAK = ByteStringRange.create("a", "k");
    ChangeStreamContinuationToken tokenAK = ChangeStreamContinuationToken.create(childAK, ByteStringRange.serializeToByteString(childAK).toStringUtf8());
    NewPartition newPartitionAK = new NewPartition(childAK, Collections.singletonList(tokenAK), watermark);
    metadataTableDao.writeNewPartition(newPartitionAK);
    assertEquals(DoFn.ProcessContinuation.resume().withResumeDelay(Duration.millis(100)), action.run(tracker, receiver, watermarkEstimator, new InitialPipelineState(startTime, false)));
    // Check what parameters were passed to OutputReceiver to verify the new partitions created by
    // DNP are correct.
