@Test
public void backlogReplicationAdjustment() throws IOException {
    SerializableSupplier<Instant> mockClock = () -> Instant.ofEpochSecond(1000);
    doFn = new ReadChangeStreamPartitionDoFn(daoFactory, actionFactory, metrics, Duration.standardSeconds(30), mockClock);
    long mutationSize = 100L;
    when(sizeEstimator.sizeOf(any())).thenReturn(mutationSize);
    doFn.setSizeEstimator(sizeEstimator);
    Range.ByteStringRange partitionRange = Range.ByteStringRange.create("", "");
    ChangeStreamContinuationToken testToken = ChangeStreamContinuationToken.create(partitionRange, "test");
    doFn.setup();
    double mutationEstimate10Second = doFn.getSize(new StreamProgress(testToken, mockClock.get().minus(Duration.standardSeconds(10)), BigDecimal.valueOf(1000), mockClock.get().minus(Duration.standardSeconds(10)), false));
    // With 30s backlogReplicationAdjustment we should have no backlog when watermarkLag is < 30s
    assertEquals(0, mutationEstimate10Second, 0);
    double mutationEstimateOneMinute = doFn.getSize(new StreamProgress(testToken, mockClock.get().minus(Duration.standardSeconds(60)), BigDecimal.valueOf(1000), mockClock.get().minus(Duration.standardSeconds(60)), false));
    // We ignore the first 30s of backlog so this should be throughput * (60 - 30)
    assertEquals(1000 * 30, mutationEstimateOneMinute, 0);
}

