@Test
public void testCreateOnlyOnce() {
    SpannerConfig config1 = SpannerConfig.create().toBuilder().setServiceFactory(serviceFactory).setProjectId(StaticValueProvider.of("project")).setInstanceId(StaticValueProvider.of("test1")).setDatabaseId(StaticValueProvider.of("test1")).build();
    SpannerAccessor acc1 = SpannerAccessor.getOrCreate(config1);
    SpannerAccessor acc2 = SpannerAccessor.getOrCreate(config1);
    SpannerAccessor acc3 = SpannerAccessor.getOrCreate(config1);
    acc1.close();
    acc2.close();
    acc3.close();
    // getDatabaseClient and close() only called once.
    verify(serviceFactory.mockSpanner(), times(1)).getDatabaseClient(DatabaseId.of("project", "test1", "test1"));
    verify(serviceFactory.mockSpanner(), times(1)).close();
}

