private PipelineResult runBatchQueryTest(SpannerIO.Read readTransform) {
    PCollection<Struct> results = pipeline.apply("read q", readTransform);
    when(mockBatchTx.partitionQuery(any(PartitionOptions.class), eq(Statement.of(QUERY_STATEMENT)), any(ReadQueryUpdateTransactionOption.class), any(ReadAndQueryOption.class))).thenReturn(Arrays.asList(fakePartition, fakePartition, fakePartition));
    when(mockBatchTx.execute(any(Partition.class))).thenReturn(ResultSets.forRows(FAKE_TYPE, FAKE_ROWS.subList(0, 2)), ResultSets.forRows(FAKE_TYPE, FAKE_ROWS.subList(2, 4)), ResultSets.forRows(FAKE_TYPE, FAKE_ROWS.subList(4, 6)));
    PAssert.that(results).containsInAnyOrder(FAKE_ROWS);
    PipelineResult result = pipeline.run();
    verifyQueryRequestMetricWasSet(readTransform.getSpannerConfig(), QUERY_NAME, "ok", 4);
    return result;
}

