@Test
public void runBatchQueryTestWithFailures() {
    pipeline.apply("read q", SpannerIO.read().withSpannerConfig(spannerConfig).withQuery(QUERY_STATEMENT).withQueryName(QUERY_NAME).withTimestampBound(TIMESTAMP_BOUND));
    when(mockBatchTx.partitionQuery(any(PartitionOptions.class), eq(Statement.of(QUERY_STATEMENT)), any(ReadQueryUpdateTransactionOption.class), any(ReadAndQueryOption.class))).thenReturn(Arrays.asList(fakePartition, fakePartition));
    when(mockBatchTx.execute(any(Partition.class))).thenReturn(ResultSets.forRows(FAKE_TYPE, FAKE_ROWS)).thenThrow(SpannerExceptionFactory.newSpannerException(ErrorCode.PERMISSION_DENIED, "Simulated Failure"));
    assertThrows("PERMISSION_DENIED: Simulated Failure", PipelineExecutionException.class, pipeline::run);
    // Query request should succeed at lease once (for partition query) and one execute may succeed.
    assertTrue(getQueryRequestMetric(spannerConfig, QUERY_NAME, "ok") >= 1);
    verifyQueryRequestMetricWasSet(spannerConfig, QUERY_NAME, "permission_denied", 1);
}

