private void runReadAllPipeline(SpannerIO.ReadAll readAllTransform) {
    PCollection<ReadOperation> reads = pipeline.apply(Create.of(ReadOperation.create().withQuery(QUERY_STATEMENT).withQueryName(QUERY_NAME), ReadOperation.create().withTable(TABLE_ID).withColumns("id", "name")));
    PCollection<Struct> results = reads.apply("read all", readAllTransform);
    when(mockBatchTx.partitionQuery(any(PartitionOptions.class), eq(Statement.of(QUERY_STATEMENT)), any(ReadQueryUpdateTransactionOption.class), any(ReadAndQueryOption.class))).thenReturn(Arrays.asList(fakePartition, fakePartition));
    when(mockBatchTx.partitionRead(any(PartitionOptions.class), eq(TABLE_ID), eq(KeySet.all()), eq(Arrays.asList("id", "name")), any(ReadQueryUpdateTransactionOption.class), any(ReadAndQueryOption.class))).thenReturn(Collections.singletonList(fakePartition));
    when(mockBatchTx.execute(any(Partition.class))).thenReturn(ResultSets.forRows(FAKE_TYPE, FAKE_ROWS.subList(0, 2)), ResultSets.forRows(FAKE_TYPE, FAKE_ROWS.subList(2, 4)), ResultSets.forRows(FAKE_TYPE, FAKE_ROWS.subList(4, 6)));
