public void testExceptionHandlingForSimpleWrite() throws InterruptedException {
    List<Mutation> mutationList = Arrays.asList(SpannerIOWriteTest.buildUpsertMutation((long) 1));
    // mock sleeper so that it does not actually sleep.
    SpannerIO.WriteToSpannerFn.sleeper = Mockito.mock(Sleeper.class);
    when(serviceFactory.mockDatabaseClient().writeAtLeastOnceWithOptions(any(), any(Options.ReadQueryUpdateTransactionOption.class))).thenThrow(SpannerExceptionFactory.newSpannerException(exceptionErrorcode, errorString));
    thrown.expect(Pipeline.PipelineExecutionException.class);
    thrown.expectMessage(errorString);
    SpannerWriteResult result = pipeline.apply(Create.of(mutationList)).apply(SpannerIO.write().withProjectId("test-project").withInstanceId("test-instance").withDatabaseId("test-database").withServiceFactory(serviceFactory).withBatchSizeBytes(0).withFailureMode(SpannerIO.FailureMode.FAIL_FAST));
    // One error
    PAssert.that(result.getFailedMutations()).satisfies(m -> {
        assertEquals(1, Iterables.size(m));
        return null;
    });
    try {
        pipeline.run().waitUntilFinish();
    } finally {
        verify(SpannerIO.WriteToSpannerFn.sleeper, callsToSleeperVerification).sleep(anyLong());
        verify(serviceFactory.mockDatabaseClient(), callsToWriteVerification).writeAtLeastOnceWithOptions(any(), any(Options.ReadQueryUpdateTransactionOption.class));
    }
}

