@Test
public void deadlineExceededFailsAfterRetries() throws InterruptedException {
    List<Mutation> mutationList = Arrays.asList(buildUpsertMutation((long) 1));
    // mock sleeper so that it does not actually sleep.
    WriteToSpannerFn.sleeper = Mockito.mock(Sleeper.class);
    // respond with all timeouts.
    when(serviceFactory.mockDatabaseClient().writeAtLeastOnceWithOptions(any(), any(ReadQueryUpdateTransactionOption.class))).thenThrow(SpannerExceptionFactory.newSpannerException(ErrorCode.DEADLINE_EXCEEDED, "simulated Timeout"));
    SpannerWriteResult result = pipeline.apply(Create.of(mutationList)).apply(SpannerIO.write().withSpannerConfig(SPANNER_CONFIG).withServiceFactory(serviceFactory).withBatchSizeBytes(0).withMaxCumulativeBackoff(Duration.standardHours(2)).withFailureMode(SpannerIO.FailureMode.REPORT_FAILURES));
    // One error
    PAssert.that(result.getFailedMutations()).satisfies(m -> {
        assertEquals(1, Iterables.size(m));
        return null;
    });
    pipeline.run().waitUntilFinish();
    long totalSleep = Mockito.mockingDetails(WriteToSpannerFn.sleeper).getInvocations().stream().mapToLong(i -> i.getArgument(0)).reduce(0L, Long::sum);
    // Total sleep should be greater then 2x maxCumulativeBackoff: 120m,
    // because the batch is repeated inidividually due REPORT_FAILURES.
    assertTrue(String.format("Should be least 7200s of sleep, got %d", totalSleep), totalSleep >= Duration.standardHours(2).getMillis());
    int numSleeps = Mockito.mockingDetails(WriteToSpannerFn.sleeper).getInvocations().size();
    // Number of write attempts should be numSleeps + 2 write attempts:
    //      1 batch attempt, numSleeps/2 batch retries,
    // then 1 individual attempt + numSleeps/2 individual retries
    verify(serviceFactory.mockDatabaseClient(), times(numSleeps + 2)).writeAtLeastOnceWithOptions(any(), any(ReadQueryUpdateTransactionOption.class));
    verifyTableWriteRequestMetricWasSet(SPANNER_CONFIG, TABLE_NAME, "ok", 0);
    verifyTableWriteRequestMetricWasSet(SPANNER_CONFIG, TABLE_NAME, "deadline_exceeded", numSleeps + 2);
}

