@Test
public void testCloseWithTimeout() throws IOException {
    Duration closeTimeout = Duration.millis(2000L);
    JmsIO.Read spec = JmsIO.read().withConnectionFactory(connectionFactory).withUsername(USERNAME).withPassword(PASSWORD).withQueue(QUEUE).withCloseTimeout(closeTimeout);
    JmsIO.UnboundedJmsSource source = new JmsIO.UnboundedJmsSource(spec);
    ScheduledExecutorService mockScheduledExecutorService = Mockito.mock(ScheduledExecutorService.class);
    ExecutorOptions options = PipelineOptionsFactory.as(ExecutorOptions.class);
    options.setScheduledExecutorService(mockScheduledExecutorService);
    ArgumentCaptor<Runnable> runnableArgumentCaptor = ArgumentCaptor.forClass(Runnable.class);
    when(mockScheduledExecutorService.schedule(runnableArgumentCaptor.capture(), anyLong(), any(TimeUnit.class))).thenReturn(null);
    JmsIO.UnboundedJmsReader reader = source.createReader(options, null);
    reader.start();
    assertFalse(getDiscardedValue(reader));
    reader.close();
    assertFalse(getDiscardedValue(reader));
    verify(mockScheduledExecutorService).schedule(any(Runnable.class), eq(closeTimeout.getMillis()), eq(TimeUnit.MILLISECONDS));
    runnableArgumentCaptor.getValue().run();
    assertTrue(getDiscardedValue(reader));
    verifyNoMoreInteractions(mockScheduledExecutorService);
}

